/** Query defines the gRPC querier service. */
export interface Query {
  /** Parameters queries the parameters of the module. */
  Params(request: QueryParamsRequest): Promise<QueryParamsResponse>;
  /** ListValidatorApplication Queries a list of ValidatorApplication items. */
  GetValidatorApplication(request: QueryGetValidatorApplicationRequest): Promise<QueryGetValidatorApplicationResponse>;
  /** ListValidatorApplication defines the ListValidatorApplication RPC. */
  ListValidatorApplication(request: QueryAllValidatorApplicationRequest): Promise<QueryAllValidatorApplicationResponse>;
  /** ListApprovedValidator Queries a list of ApprovedValidator items. */
  GetApprovedValidator(request: QueryGetApprovedValidatorRequest): Promise<QueryGetApprovedValidatorResponse>;
  /** ListApprovedValidator defines the ListApprovedValidator RPC. */
  ListApprovedValidator(request: QueryAllApprovedValidatorRequest): Promise<QueryAllApprovedValidatorResponse>;
  /** GetOperatorRotation queries one rotation by id. */
  GetOperatorRotation(request: QueryGetOperatorRotationRequest): Promise<QueryGetOperatorRotationResponse>;
  /** ListOperatorRotation queries every rotation ever opened. */
  ListOperatorRotation(request: QueryAllOperatorRotationRequest): Promise<QueryAllOperatorRotationResponse>;
  /**
   * PendingOperatorRotation queries the open rotation against one operator, if
   * there is one. This is the query a delegator runs before deciding whether to
   * undelegate, so it answers from the address they already know rather than
   * from a rotation id they would have to go and find.
   */
  PendingOperatorRotation(request: QueryPendingOperatorRotationRequest): Promise<QueryPendingOperatorRotationResponse>;
  /**
   * Concentration reports what every declared entity, owner and jurisdiction
   * currently holds, against its ceiling.
   *
   * This is the supervisor's query. Under equal seats a ceiling is a count out
   * of a count, so the answer is meant to be checked against a list of admitted
   * validators by somebody who is not recomputing anything — which is the whole
   * argument for declaring ownership on-chain rather than filing it somewhere.
   */
  Concentration(request: QueryConcentrationRequest): Promise<QueryConcentrationResponse>;
  /** ListDemotion queries every demotion currently in force. */
  ListDemotion(request: QueryAllDemotionRequest): Promise<QueryAllDemotionResponse>;
}

